<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='activity_log';$pageTitle='Activity Log';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];if(fo_has_table($conn,'finance_activity_log')){$s=$conn->prepare("SELECT * FROM finance_activity_log WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 200");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Audit & Accountability</span><h2>Activity Log</h2><p>Recorded stipend preparation and approval actions.</p></div></div><div class="fo-card"><div class="fo-activity"><?php foreach($rows as $x):?><article><i class="fas fa-fingerprint"></i><div><strong><?= e(fo_label($x['action'])) ?></strong><span><?= e(fo_datetime($x['created_at'])) ?></span><p><?= e($x['description']) ?></p></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="fo-empty"><i class="fas fa-fingerprint"></i><strong>No activity recorded</strong></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>